var t=`0967-bibimbap`;var a=`world-0967`;var o=`KR`;var s=`east-asia`;var n=4;var r=59;var u={en:`Bibimbap`,ua:`Пібімпап`};var g={en:`Bibimbap is a South Korea dish made with calrose rice, beef sirloin, shiitake mushroom, light soy sauce. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Пібімпап, страва кухні країни Південна Корея. Основні складники: рис калроуз, яловичий сирлойн, шиїтаке, світлий соєвий соус. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 25 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 25 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`calrose-rice`,420,`g`],[`water`,820,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`beef-sirloin`,370,`g`],[`shiitake-mushroom`,150,`g`],[`canola-oil`,35,`ml`],[`light-soy-sauce`,35,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`carrot`,170,`g`],[`spinach`,230,`g`],[`bean-sprouts`,240,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 7 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 7 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:7,i:[[`chicken-egg`,4,`pcs`]]},{en:`Arrange hot rice with separately cooked vegetables, cooked beef, egg and gochujang; each diner mixes the bibimbap before eating.`,ua:`Викладіть гарячий рис з окремо підготовленими овочами, готовою яловичиною, яйцем і кочуджаном; кожен перемішує пібімпап перед їдою.`,t:[`layered-assembly`,`garnishing`],m:7,i:[[`gochujang`,90,`g`],[`toasted-sesame-oil`,35,`ml`],[`white-sesame-seeds`,25,`g`]]}];var d={slug:t,id:a,country:`KR`,region:s,servings:4,minutes:59,title:u,text:g,steps:h};export{o as country,d as default,a as id,r as minutes,s as region,n as servings,t as slug,h as steps,g as text,u as title};